  title text not null,
  description text,
  starts_on date not null,
  ends_on date,
  starts_at timestamptz,
  ends_at timestamptz,
  is_working_day boolean not null default true,
  audience text not null default 'all' check (audience in ('staff','families','all')),
  programme_ids uuid[] not null default '{}',
  linked_type text,
  linked_id uuid,
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, branch_id) references core.branches(org_id, id),
  check (ends_on is null or ends_on >= starts_on)
);
create index calendar_events_branch on core.calendar_events(org_id, branch_id);
