create trigger trg_touch before update on core.calendar_events for each row execute function app.touch_updated_at();
grant select, insert, update, delete on core.calendar_events to authenticated, crm_server, os_server, erp_server;
grant select on core.calendar_events to platform_admin_server;
select app.apply_core_rls('calendar_events', 'staff', '*', 'calendar', 'audience in (''families'',''all'')', null);

